import{t as e}from"./index-CcTmXcgA.js";var t={meta:e,chapters:JSON.parse(`[{"number":1,"title":"The Boy Who Lived","summary":"On an odd day full of owls and cloaked strangers, Dumbledore, McGonagall and Hagrid leave a baby, Harry Potter, on the Dursleys’ doorstep. His parents are dead, but the dark wizard who attacked them has vanished.","details":["Mr. and Mrs. Dursley of number four, Privet Drive, are proud of being perfectly normal. Vernon runs a drill company called Grunnings; Petunia spends her time spying on the neighbours; their baby son Dudley is, in their view, perfect. Their one secret is Petunia’s sister, Mrs. Potter, and her strange husband, whom they pretend not to have.","One dull Tuesday, Vernon notices odd things: a cat that seems to be reading a map, people in cloaks celebrating in the street, owls flying in broad daylight, and whispers about “the Potters” and their son, Harry. That night a tall, silver-bearded old man, Albus Dumbledore, appears on Privet Drive and dims every streetlamp with a lighter-like device. The tabby cat that has watched the Dursleys all day turns into Professor McGonagall.","They discuss the news. The dark wizard most people fear to name, whom Dumbledore calls Voldemort, went to the Potters’ home in Godric’s Hollow and killed Lily and James Potter. But he failed to kill their baby son, and somehow his power broke and he disappeared. Dumbledore has decided Harry should be raised by his aunt and uncle, his only family, far from the fame waiting for him in the wizarding world. McGonagall protests that the Dursleys are the worst sort of Muggles (non-magical people).","The huge, wild-haired Hagrid lands on a flying motorbike, borrowed from someone called Sirius Black, carrying baby Harry, who has a lightning-shaped cut on his forehead. Dumbledore leaves Harry on the doorstep with a letter. All over the country, witches and wizards raise their glasses “to Harry Potter — the boy who lived.”"],"characters":["vernon-dursley","petunia-dursley","dudley-dursley","albus-dumbledore","minerva-mcgonagall","voldemort","lily-potter","james-potter","harry-potter","rubeus-hagrid","sirius-black","dedalus-diggle"]},{"number":2,"title":"The Vanishing Glass","summary":"Ten years later, Harry sleeps in a cupboard under the stairs and is bullied by his spoiled cousin Dudley. On a trip to the zoo, Harry talks to a snake, and the glass of its tank mysteriously vanishes.","details":["Nearly ten years have passed. Harry, almost eleven, lives in the cupboard under the stairs. He is small and skinny, with messy black hair, bright green eyes, taped-up round glasses and a thin lightning-shaped scar. The Dursleys told him his parents died in a car crash, and they forbid questions. Dudley, now large and spoiled, throws a tantrum because he has only thirty-six birthday presents, one fewer than last year.","Strange things tend to happen around Harry: hair that grows back overnight after a terrible haircut, a hideous sweater that shrinks until it won’t fit him, and once finding himself on the school roof while running from Dudley’s gang. The Dursleys always blame him.","Because Mrs. Figg, the cat-loving neighbour who usually minds Harry, has broken her leg, he is taken along on Dudley’s birthday trip to the zoo with Dudley’s friend Piers Polkiss. In the reptile house a large boa constrictor winks at Harry, and the two have a conversation: it was bred in the zoo and has never seen Brazil. When Dudley shoves Harry aside, the glass of the tank simply vanishes and the snake escapes.","Back home, Harry is locked in his cupboard for a long punishment. He thinks about the flash of green light he remembers from the crash, his dreams of a flying motorbike, and the odd strangers who sometimes bow to him in the street and then vanish."],"characters":["harry-potter","dudley-dursley","vernon-dursley","petunia-dursley","arabella-figg","piers-polkiss"]},{"number":3,"title":"The Letters from No One","summary":"A letter arrives for Harry, addressed to his cupboard. Uncle Vernon destroys it, but more and more keep coming, until he flees with the family to a shack on a rock at sea. At midnight, on Harry’s birthday, someone knocks.","details":["When Harry is finally let out, the summer holidays begin. Dudley is getting the uniform for Smeltings, his father’s old school, while Harry is to attend the local comprehensive. Then a letter arrives for Harry, written in emerald-green ink and addressed to “Mr. H. Potter, The Cupboard under the Stairs.” Nobody has ever written to him before.","Vernon snatches it, goes pale, and whispers with Petunia. They move Harry into Dudley’s second bedroom, as if afraid someone is watching. But the letters keep coming: through the mail slot, slipped inside eggs, and finally dozens pouring down the chimney on a Sunday, when there is no post.","Vernon snaps and drives the family away, ending up at a miserable shack on a rock in the sea during a storm. Harry lies on the floor counting down to midnight and his eleventh birthday. As the minute arrives, there is a tremendous knock at the door."],"characters":["harry-potter","vernon-dursley","petunia-dursley","dudley-dursley"]},{"number":4,"title":"The Keeper of the Keys","summary":"The giant Hagrid breaks down the door and tells Harry the truth: he is a wizard, he has a place at Hogwarts School of Witchcraft and Wizardry, and his parents were murdered by Voldemort, whose curse failed on Harry.","details":["A giant of a man bursts in: Hagrid, Keeper of Keys and Grounds at Hogwarts. He brings Harry a slightly squashed birthday cake and is horrified to learn the Dursleys never told him anything. He hands Harry his letter: he has been accepted at Hogwarts School of Witchcraft and Wizardry.","Hagrid explains that Harry’s parents were a witch and a wizard. A dark wizard, whose name Hagrid can barely bring himself to say, gathered followers and spread terror. He killed Lily and James, but when he tried to kill Harry the curse failed, leaving only the scar, and he vanished. That is why every witch and wizard knows Harry’s name. Hagrid doesn’t believe the dark wizard is dead, just too weak to carry on.","Aunt Petunia bursts out that she always knew: her sister Lily was a witch, the family’s favourite, and she married another “freak.” The Dursleys hid the truth hoping to squash the magic out of Harry. When Vernon insults Dumbledore, Hagrid angrily gives Dudley a pig’s tail with his pink umbrella. Hagrid lets slip that he was expelled from Hogwarts in his third year and isn’t supposed to do magic."],"characters":["rubeus-hagrid","harry-potter","vernon-dursley","petunia-dursley","dudley-dursley","lily-potter","james-potter","voldemort","albus-dumbledore"]},{"number":5,"title":"Diagon Alley","summary":"Hagrid takes Harry to London to shop in Diagon Alley. Harry discovers he has a fortune at the wizard bank Gringotts, buys a wand that turns out to be connected to his scar, and meets the people of the wizarding world.","details":["Hagrid explains wizard money (gold Galleons, silver Sickles, bronze Knuts) and Gringotts, the goblin-run bank. In London they enter the Leaky Cauldron, a dingy pub Muggles can’t see, where everyone wants to shake Harry’s hand, including the nervous, stuttering Professor Quirrell, who will teach him Defence Against the Dark Arts. Hagrid taps a brick wall, and it opens onto Diagon Alley.","At Gringotts the goblin Griphook takes them by rattling cart to Harry’s vault, which is full of gold his parents left him. Hagrid also collects a small, grubby package from vault 713 on secret Hogwarts business for Dumbledore. In Madam Malkin’s robe shop, Harry meets a pale, drawling boy who boasts about Quidditch, sneers at Hagrid and says children from Muggle families shouldn’t be let into Hogwarts.","Hagrid buys Harry a snowy owl for his birthday. At Ollivanders, wand after wand is wrong until one of holly and phoenix feather, eleven inches, sends sparks flying. Mr. Ollivander finds it curious: the phoenix that gave that feather gave one other, and its brother wand gave Harry his scar. Hagrid explains that the dark wizard was a Slytherin, and that Harry should not be afraid of not knowing magic yet. He leaves Harry with a train ticket for platform nine and three-quarters."],"characters":["rubeus-hagrid","harry-potter","quirinus-quirrell","dedalus-diggle","tom-the-barman","griphook","madam-malkin","pale-boy","garrick-ollivander","voldemort","albus-dumbledore"]},{"number":6,"title":"The Journey from Platform Nine and Three-Quarters","summary":"With help from the red-headed Weasley family, Harry gets onto the Hogwarts Express. On the train he befriends Ron Weasley, meets bossy Hermione Granger and forgetful Neville, and refuses the friendship of snobbish Draco Malfoy.","details":["Harry names his owl Hedwig. Uncle Vernon drops him at King’s Cross station and laughs when there is no platform nine and three-quarters. Then Harry overhears a plump woman fussing about the station being “packed with Muggles”: Mrs. Weasley, with her red-haired children. She tells him to walk straight at the barrier between platforms nine and ten, and he passes through onto a platform with a scarlet steam engine, the Hogwarts Express. The twins, Fred and George, help with his trunk and notice his scar.","Their youngest brother, Ron, shares Harry’s compartment. He has five older brothers to live up to (Bill, Charlie, Percy the prefect, and the twins) plus a little sister, Ginny, and his only pet is a sleepy hand-me-down rat called Scabbers. Ron mentions that someone tried to break into a vault at Gringotts. Harry buys the whole sweets trolley to share, and from a Chocolate Frog card learns about Albus Dumbledore, famous for, among other things, his work on alchemy with his partner Nicolas Flamel.","A round-faced boy, Neville, has lost his toad, and a bossy, bushy-haired girl, Hermione Granger, helps search. She has memorized all her textbooks and already knows who Harry is. Then the pale boy from Madam Malkin’s arrives with two thuggish friends, Crabbe and Goyle. He introduces himself as Draco Malfoy, mocks Ron’s family and offers to help Harry make the right sort of friends. Harry refuses. Scabbers bites Goyle. At Hogsmeade station Hagrid leads the first-years across a black lake in little boats to the castle."],"characters":["hedwig","harry-potter","vernon-dursley","molly-weasley","fred-weasley","george-weasley","percy-weasley","ginny-weasley","ron-weasley","bill-weasley","charlie-weasley","scabbers","lee-jordan","albus-dumbledore","nicolas-flamel","neville-longbottom","hermione-granger","draco-malfoy","vincent-crabbe","gregory-goyle","rubeus-hagrid"]},{"number":7,"title":"The Sorting Hat","summary":"The first-years are sorted into houses by a singing hat. Harry asks not to be put in Slytherin and joins Ron, Hermione and Neville in Gryffindor. At the feast, his scar burns when a hook-nosed teacher looks at him.","details":["Professor McGonagall explains that each student will join one of four houses (Gryffindor, Hufflepuff, Ravenclaw or Slytherin) which win and lose points all year in the race for the House Cup. Ghosts float through the waiting room. In the Great Hall, under a ceiling enchanted to look like the night sky, an old patched hat sings about the houses.","One by one the first-years put on the Sorting Hat. Hermione goes to Gryffindor, as does Neville; Draco Malfoy goes straight to Slytherin. When Harry’s turn comes, the hat tells him he could be great in Slytherin, but Harry silently pleads “not Slytherin,” and the hat shouts “Gryffindor!” Ron joins him to huge cheers, with the twins chanting “We got Potter!”","Dumbledore says a few odd words, and a feast appears. Nearly Headless Nick, Gryffindor’s ghost, shows how his head hangs by a sliver of skin. Seamus Finnigan and Neville describe their families. Looking at the staff table, Harry catches the eye of a teacher with greasy black hair and a hooked nose, talking to Professor Quirrell in his purple turban, and feels a sharp pain in his scar. Percy says the teacher is Professor Snape, who teaches Potions and is said to want Quirrell’s job.","Dumbledore warns that the Forbidden Forest is off limits and that the third-floor corridor on the right-hand side is forbidden to anyone who does not wish to die a very painful death. Percy leads the Gryffindors past the poltergeist Peeves to a portrait of a Fat Lady, who opens at the password. That night Harry dreams of a turban that tells him to transfer to Slytherin, a flash of green light, and high, cold laughter."],"characters":["minerva-mcgonagall","harry-potter","ron-weasley","hermione-granger","neville-longbottom","draco-malfoy","sorting-hat","fat-friar","nearly-headless-nick","bloody-baron","albus-dumbledore","seamus-finnigan","dean-thomas","percy-weasley","fred-weasley","george-weasley","severus-snape","quirinus-quirrell","argus-filch","peeves","fat-lady","vincent-crabbe","gregory-goyle"]},{"number":8,"title":"The Potions Master","summary":"Harry struggles with the castle and his classes. In his first Potions lesson, Professor Snape picks on him relentlessly. Over tea, Harry finds a newspaper clipping: the Gringotts vault Hagrid emptied was broken into the same day.","details":["Everyone stares at Harry in the corridors. The castle is full of tricks: staircases that move, doors that won’t open, and Peeves dropping things on people. The caretaker, Argus Filch, and his cat, Mrs. Norris, seem to sense rule-breakers. Classes begin: Herbology with Professor Sprout, History of Magic taught by the ghost Professor Binns, Charms with the tiny Professor Flitwick, who falls off his books of excitement at Harry’s name, and strict Transfiguration with McGonagall. Quirrell’s Defence classroom smells of garlic, said to ward off a vampire, and he claims his turban was a gift from an African prince.","On Friday the Gryffindors have double Potions with the Slytherins in a cold dungeon. Snape calls Harry “our new celebrity” and fires questions at him he can’t answer (what you get from asphodel and wormwood, where to find a bezoar), ignoring Hermione’s raised hand, and takes points for his “cheek.” When Neville melts a cauldron and gets covered in boils, Snape blames Harry for not stopping him.","That afternoon Harry and Ron visit Hagrid’s hut, with its enormous boarhound, Fang, and teeth-breaking rock cakes. Under the tea cozy Harry finds a Daily Prophet clipping: Gringotts vault 713 was broken into on Harry’s birthday, but nothing was taken because it had been emptied earlier that same day. Hagrid emptied that vault. Hagrid avoids Harry’s questions, and also brushes off his question about why Snape seems to hate him."],"characters":["harry-potter","ron-weasley","hermione-granger","neville-longbottom","peeves","argus-filch","mrs-norris","pomona-sprout","professor-binns","filius-flitwick","minerva-mcgonagall","quirinus-quirrell","severus-snape","draco-malfoy","rubeus-hagrid","fang","hedwig"]},{"number":9,"title":"The Midnight Duel","summary":"At his first flying lesson, Harry shows a natural gift and is made Gryffindor’s Seeker. Tricked into a midnight duel by Malfoy, Harry, Ron, Hermione and Neville stumble into the forbidden corridor and find a three-headed dog guarding a trapdoor.","details":["Neville receives a Remembrall from his gran. At the first flying lesson with Madam Hooch, Neville loses control, falls and breaks his wrist. While Hooch takes him to the hospital wing, Malfoy grabs the Remembrall and flies off with it. Harry, who has never been on a broom, kicks off after him and turns out to be a born flier, catching the ball in a steep dive just before it hits a window.","Professor McGonagall saw it all. Instead of punishing Harry, she takes him to Oliver Wood, captain of the Gryffindor Quidditch team, and makes him the team’s Seeker, the youngest house player in a century. His father, she mentions, was an excellent player too.","Malfoy challenges Harry to a wizard’s duel at midnight in the trophy room, with Crabbe as his second and Ron as Harry’s. Hermione tries to stop them and ends up locked out of Gryffindor Tower, along with Neville, who has forgotten the password. Malfoy never comes: he has tipped off Filch. Fleeing, they end up at a locked door, which Hermione opens with a spell.","They are in the forbidden third-floor corridor, face to face with a gigantic three-headed dog. They escape back to the common room. Hermione points out that the dog was standing on a trapdoor: it is guarding something. Harry thinks he knows what: Hagrid’s grubby little package from vault 713."],"characters":["neville-longbottom","harry-potter","ron-weasley","hermione-granger","draco-malfoy","rolanda-hooch","minerva-mcgonagall","oliver-wood","vincent-crabbe","gregory-goyle","pansy-parkinson","argus-filch","peeves","fat-lady","three-headed-dog","mrs-norris"]},{"number":10,"title":"Hallowe’en","summary":"Harry gets a top racing broom and learns the rules of Quidditch. On Halloween, a troll gets into the castle; Harry and Ron rescue Hermione from it in a girls’ bathroom, and the three become friends.","details":["At breakfast Harry receives a long parcel: a Nimbus Two Thousand racing broom, sent by McGonagall. Malfoy tries to get him in trouble for having it, but Professor Flitwick already knows. Oliver Wood teaches Harry the game: three Chasers score with the Quaffle through hoops guarded by the Keeper; two Beaters swat away the violent Bludgers; and the Seeker must catch the tiny, darting Golden Snitch, which ends the game and is worth 150 points.","In Charms the class learns the levitation spell. Hermione gets her feather floating at once and corrects Ron’s pronunciation; afterwards Ron mocks her as a know-it-all with no friends. She overhears and spends the afternoon crying in the girls’ bathroom.","At the Halloween feast Professor Quirrell runs in shouting that there is a troll in the dungeons, then faints. Dumbledore sends the students to their dormitories, but Harry and Ron realize Hermione doesn’t know. They see the twelve-foot mountain troll go into a room and lock it in, then hear a scream: it’s the girls’ bathroom.","They fight the troll. Harry jumps on its back and jams his wand up its nose, and Ron finally makes the levitation spell work, dropping the troll’s own club on its head. McGonagall, Snape and Quirrell rush in. Hermione lies that she went looking for the troll herself and was saved by the boys, losing Gryffindor five points; the boys earn five points each. From then on, Hermione is their friend."],"characters":["harry-potter","minerva-mcgonagall","draco-malfoy","filius-flitwick","oliver-wood","hermione-granger","ron-weasley","quirinus-quirrell","albus-dumbledore","mountain-troll","severus-snape","percy-weasley"]},{"number":11,"title":"Quidditch","summary":"Harry spots Snape’s mauled leg and suspects he tried to get past the three-headed dog. During Harry’s first Quidditch match his broom goes wild; Hermione, sure Snape is jinxing it, sets his robes on fire. Hagrid lets slip the name Nicolas Flamel.","details":["Snape confiscates Harry’s library book, Quidditch Through the Ages. When Harry goes to the staff room to ask for it back, he finds Snape with a bloody, mangled leg, complaining to Filch about keeping an eye on “all three heads.” Harry is sure Snape let the troll in on Halloween as a distraction while he tried to get past the dog.","At the first match, Gryffindor against Slytherin, Lee Jordan commentates while McGonagall reins him in. Gryffindor scores, Slytherin’s captain Marcus Flint fouls, and then Harry’s broom starts bucking and rolling as though trying to throw him off. Hermione grabs Hagrid’s binoculars and sees Snape staring at Harry, muttering nonstop without blinking.","Hermione races round the stands, knocking Professor Quirrell over on the way, and sets Snape’s robes on fire with a jar of blue flames. The broom stops jerking. Harry dives, nearly swallows the Snitch, and catches it in his mouth: Gryffindor wins.","Over tea, Harry and his friends tell Hagrid they believe Snape cursed the broom. Hagrid refuses to believe it of a Hogwarts teacher, and lets slip that the three-headed dog is his, named Fluffy, and that what it guards is strictly between Dumbledore and someone called Nicolas Flamel."],"characters":["severus-snape","harry-potter","argus-filch","ron-weasley","hermione-granger","lee-jordan","minerva-mcgonagall","oliver-wood","marcus-flint","fred-weasley","george-weasley","rubeus-hagrid","quirinus-quirrell","three-headed-dog","nicolas-flamel","draco-malfoy","neville-longbottom"]},{"number":12,"title":"The Mirror of Erised","summary":"Over Christmas, Harry receives an Invisibility Cloak that belonged to his father. Exploring under it, he finds a mirror that shows his dead parents. Dumbledore explains that it shows your deepest desire, and warns him not to dwell on dreams.","details":["Harry, Ron and Hermione search the library for Nicolas Flamel without luck. Harry stays at Hogwarts for Christmas, as does Ron, whose parents are visiting his brother Charlie in Romania, where he studies dragons. On Christmas morning Harry is amazed to have presents: a flute Hagrid carved, a hand-knitted sweater and fudge from Mrs. Weasley, a fifty-pence coin from the Dursleys, and a silvery cloak that makes the wearer invisible, with an unsigned note saying it belonged to his father and to use it well.","That night Harry sneaks into the Restricted Section of the library under the cloak. A book screams when he opens it, and fleeing Filch, he slips into an unused classroom. There stands a tall mirror with an inscription across the top. In it Harry sees himself surrounded by his family: his mother, with his own green eyes, his father, with his untidy hair, and many more relatives.","He brings Ron, who sees himself as Head Boy and Quidditch captain, holding the House Cup. On the third night Dumbledore is waiting. He explains that the Mirror of Erised shows the deepest, most desperate desire of our hearts, which has driven people mad. It will be moved, and Harry must not look for it again: “It does not do to dwell on dreams and forget to live.” Asked what he sees, Dumbledore says he sees himself holding a pair of thick woollen socks."],"characters":["harry-potter","ron-weasley","hermione-granger","rubeus-hagrid","charlie-weasley","molly-weasley","vernon-dursley","petunia-dursley","fred-weasley","george-weasley","percy-weasley","argus-filch","severus-snape","albus-dumbledore","lily-potter","james-potter","draco-malfoy","nicolas-flamel"]},{"number":13,"title":"Nicolas Flamel","summary":"A Chocolate Frog card finally tells the friends who Nicolas Flamel is: maker of the Sorcerer’s Stone, which grants gold and eternal life. The dog must be guarding it. After a quick Quidditch win, Harry overhears Snape threatening Quirrell in the forest.","details":["Harry worries because Snape will referee the next Quidditch match. Neville hops in, his legs stuck together by Malfoy’s Leg-Locker Curse; Hermione frees him, and Harry tells him he’s worth twelve of Malfoy and gives him a Chocolate Frog. The card inside is Dumbledore again, and Harry remembers where he read the name: Dumbledore’s work with his partner Nicolas Flamel.","Hermione fetches a huge old book. Flamel is the only known maker of the Sorcerer’s Stone, a legendary substance that turns metal into gold and produces the Elixir of Life, which makes the drinker immortal. Flamel is 665 years old. The three-headed dog must be guarding the Stone, and Snape must want it.","Dumbledore comes to watch the match, and Snape, refereeing spitefully, has no chance to do harm: Harry catches the Snitch within about five minutes. Afterward Harry sees a hooded Snape slip into the Forbidden Forest and follows on his broom. He overhears Snape pressing a frightened Quirrell to find out how to get past “that beast of Hagrid’s,” warning him about his “hocus-pocus” and to decide where his loyalties lie.","Harry tells Ron and Hermione his conclusion: other teachers have placed protections around the Stone, Quirrell must have cast an anti-Dark Arts spell that Snape needs to break, and the Stone is safe only as long as Quirrell holds out against Snape."],"characters":["harry-potter","severus-snape","neville-longbottom","draco-malfoy","hermione-granger","ron-weasley","albus-dumbledore","nicolas-flamel","quirinus-quirrell","rubeus-hagrid","vincent-crabbe","gregory-goyle"]},{"number":14,"title":"Norbert the Norwegian Ridgeback","summary":"Hagrid has won a dragon egg from a stranger in a pub and hatches a baby dragon, Norbert. With help from Ron’s brother Charlie, the friends smuggle the dragon out at midnight, but Harry and Hermione are caught by Filch.","details":["Quirrell seems braver than expected, as the Stone apparently remains safe. Exams are coming, and Hermione makes study timetables. In the library the friends find Hagrid reading about dragons. In his sweltering hut he admits he is incubating a dragon egg in the fire, won in a card game from a hooded stranger at the village pub. He also lists the protections around the Stone: spells by Professors Sprout, Flitwick, McGonagall, Quirrell and Snape, and Dumbledore’s own, besides Fluffy. Only he and Dumbledore know how to get past Fluffy.","The egg hatches into a Norwegian Ridgeback, and Malfoy sees it through the window. Hagrid names it Norbert. Dragons are illegal, and Norbert grows fast. Ron gets bitten, and his hand swells horribly, sending him to Madam Pomfrey in the hospital wing, where Malfoy borrows a book in which Ron had left a letter from Charlie.","Charlie’s friends will collect Norbert at midnight on Saturday from the top of the tallest tower. Under the Invisibility Cloak, Harry and Hermione haul the crate up, while Malfoy, out of bed to catch them, is caught by McGonagall instead. The handover goes perfectly. But in their relief they leave the cloak at the top of the tower, and Filch is waiting at the bottom of the stairs."],"characters":["quirinus-quirrell","hermione-granger","harry-potter","ron-weasley","rubeus-hagrid","pomona-sprout","filius-flitwick","minerva-mcgonagall","severus-snape","albus-dumbledore","three-headed-dog","norbert","draco-malfoy","charlie-weasley","madam-pomfrey","fang","argus-filch"]},{"number":15,"title":"The Forbidden Forest","summary":"Gryffindor loses 150 points and the whole school turns on Harry. Serving detention with Hagrid in the Forbidden Forest, Harry finds a hooded figure drinking a dead unicorn’s blood and is saved by the centaur Firenze.","details":["McGonagall takes fifty points each from Harry, Hermione and Neville, who had tried to warn them about Malfoy, and gives Malfoy a detention too. Gryffindor drops from first to last, and almost everyone, even Gryffindors, turns on Harry. He vows to stop meddling. But passing a classroom, he hears Quirrell pleading “No — no — not again, please,” and guesses Snape has finally broken him. Ron and Hermione persuade him to wait.","The detention is with Hagrid in the Forbidden Forest: something has been killing unicorns. They meet two centaurs, Ronan and Bane, who only say that Mars is bright tonight. The group splits; Malfoy scares Neville into sending up red sparks, so Hagrid swaps Neville for Harry, who goes on with Malfoy and Fang.","In a clearing they find a dead unicorn, and a hooded figure crawls out of the shadows and drinks its silvery blood. Malfoy and Fang bolt; Harry’s scar explodes with pain. A young centaur, Firenze, charges the figure off and carries Harry to safety, to Bane’s fury that he has meddled with what the planets foretell.","Firenze explains that unicorn blood keeps you alive even near death, but at a terrible price: a cursed half-life. Only someone desperate enough, waiting for something that will restore full strength, like the Stone, would do it. Harry realizes what Firenze means: the figure was Voldemort, and Snape wants the Stone for him. Back in bed, Harry finds his Invisibility Cloak returned with a note: “Just in case.”"],"characters":["minerva-mcgonagall","harry-potter","hermione-granger","neville-longbottom","draco-malfoy","ron-weasley","quirinus-quirrell","severus-snape","argus-filch","rubeus-hagrid","fang","ronan","bane","hooded-figure","firenze","voldemort"]},{"number":16,"title":"Through the Trapdoor","summary":"Harry realizes Hagrid told a stranger how to get past Fluffy. With Dumbledore away, Harry, Ron and Hermione go after the Stone themselves, getting through a series of enchanted obstacles until Harry goes on alone.","details":["Exams take place in sweltering heat, while Harry’s scar keeps prickling. Then he realizes how odd it was that a stranger happened to have a dragon egg, which is the one thing Hagrid wants most. Hagrid admits the stranger, who kept his hood up, asked about Fluffy, and Hagrid told him the secret: play it music and it falls asleep.","They rush to tell Dumbledore, but McGonagall says he has just left for London, called away by an urgent owl from the Ministry of Magic. They decide to go after the Stone that night. Neville tries to stop them, and Hermione freezes him with a full Body-Bind.","Under the cloak they find the door open and a harp already enchanted to play beside the sleeping Fluffy. Harry plays Hagrid’s flute, and they drop through the trapdoor. Hermione defeats the strangling Devil’s Snare with fire. Harry, on a broom, catches the right winged key out of hundreds. On a giant chessboard Ron directs the game and sacrifices himself so Harry can checkmate. A troll lies already knocked out. Finally, a riddle of seven potion bottles guarded by fire: Hermione solves it.","There is enough potion for only one person to go on through the black flames. Hermione drinks the potion to go back, tend Ron and send an owl to Dumbledore. Harry walks through the fire into the last chamber. Someone is already there, but it isn’t Snape. It isn’t even Voldemort."],"characters":["harry-potter","ron-weasley","hermione-granger","rubeus-hagrid","three-headed-dog","minerva-mcgonagall","albus-dumbledore","neville-longbottom","severus-snape","voldemort","peeves","mountain-troll"]},{"number":17,"title":"The Man with Two Faces","summary":"It is Quirrell, who serves Voldemort and shares his body. Snape had been protecting Harry all along. Harry gets the Stone from the Mirror of Erised and holds out until Dumbledore saves him. Gryffindor wins the House Cup.","details":["Quirrell is waiting, his stammer gone. He reveals that he jinxed Harry’s broom, Snape was muttering a counter-curse to save him, and Snape refereed the next match to stop Quirrell trying again. Quirrell let the troll in on Halloween; Snape, already suspicious, went straight to the third floor to head him off. Quirrell met Voldemort in Albania and has served him since; he failed to steal the Stone from Gringotts and has been punished for it. The pleading Harry overheard was Quirrell begging his master.","The Stone is hidden in the Mirror of Erised, and Quirrell can’t work out how to get it. A high voice tells him to use the boy. Harry looks into the mirror and sees his reflection put the Stone in his pocket, and feels it really arrive there. Quirrell unwraps his turban: on the back of his head is a second face, Voldemort, who has been sharing Quirrell’s body and drinking unicorn blood to survive. Voldemort offers to bring Harry’s parents back, but Harry refuses. When Quirrell grabs him, his hands blister and burn at Harry’s touch. Harry fights on in agony until he blacks out.","He wakes in the hospital wing. Dumbledore explains: he arrived in time. The Stone has been destroyed with Flamel’s agreement, and Voldemort, who left Quirrell to die, is still out there. Harry’s mother died to save him, and love that powerful leaves its own protection, which is why Quirrell could not bear to touch him. Dumbledore sent him the cloak. Snape hated Harry’s father, who once saved his life, and has been protecting Harry to repay the debt. The mirror gave the Stone only to someone who wanted to find it but not use it.","Hagrid gives Harry an album of photos of his parents. At the end-of-year feast Slytherin seems to have won the House Cup, until Dumbledore awards last-minute points: fifty to Ron for chess, fifty to Hermione for logic, sixty to Harry for courage, and ten to Neville for standing up to his friends. Gryffindor wins. Harry goes home for the summer knowing the Dursleys don’t know he isn’t allowed to use magic outside school."],"characters":["quirinus-quirrell","harry-potter","severus-snape","voldemort","hooded-figure","albus-dumbledore","nicolas-flamel","lily-potter","james-potter","madam-pomfrey","ron-weasley","hermione-granger","rubeus-hagrid","neville-longbottom","draco-malfoy","molly-weasley","fred-weasley","george-weasley","ginny-weasley","vernon-dursley","petunia-dursley","dudley-dursley"]}]`),characters:JSON.parse(`[{"id":"albus-dumbledore","name":"Albus Dumbledore","firstChapter":1,"importance":"major","group":"Hogwarts staff","aliases":[{"name":"Professor Dumbledore","from":1}],"tagline":[{"from":1,"text":"A tall, silver-bearded wizard who leaves baby Harry with the Dursleys."},{"from":4,"text":"Headmaster of Hogwarts, the greatest wizard of the age."},{"from":17,"text":"Hogwarts’ headmaster, who saved Harry and explains the year’s mysteries."}],"description":[{"from":1,"text":"Tall, thin and very old, with a long silver beard, half-moon spectacles and a crooked nose. He is the one wizard willing to call Voldemort by name, and he decides baby Harry should grow up with his aunt and uncle, away from his fame."},{"from":4,"text":"Hagrid reveres him as the greatest headmaster Hogwarts ever had, and the only wizard Voldemort feared."},{"from":6,"text":"His Chocolate Frog card says he defeated the dark wizard Grindelwald, discovered twelve uses of dragon’s blood, and worked on alchemy with his partner Nicolas Flamel."},{"from":7,"text":"At the start-of-term feast he seems a little eccentric, but warns the school sternly about the forbidden third-floor corridor."},{"from":12,"text":"He finds Harry at the Mirror of Erised and explains it kindly, telling him not to dwell on dreams. He claims he sees himself holding a pair of woollen socks."},{"from":16,"text":"He is called away to the Ministry of Magic on the very night the Stone is in danger."},{"from":17,"text":"He returns in time to save Harry. He reveals that he sent Harry the cloak, that the Stone has been destroyed, and that Lily’s sacrifice protects Harry. He also hid the Stone in the mirror so only someone who didn’t want to use it could get it. His last-minute points win Gryffindor the House Cup."}],"moments":[{"chapter":1,"text":"Left baby Harry on the Dursleys’ doorstep with a letter."},{"chapter":12,"text":"Explained the Mirror of Erised to Harry."},{"chapter":13,"text":"Came to watch the Quidditch match Snape refereed."},{"chapter":16,"text":"Was called away to London by an urgent message."},{"chapter":17,"text":"Saved Harry from Quirrell and explained what had happened."},{"chapter":17,"text":"Awarded the last-minute points that won Gryffindor the House Cup."}]},{"id":"dedalus-diggle","name":"Dedalus Diggle","firstChapter":1,"importance":"minor","group":"Wizarding world","aliases":[],"tagline":[{"from":1,"text":"An excitable wizard in a violet top hat."}],"description":[{"from":1,"text":"McGonagall suspects him of setting off the shooting stars that celebrated Voldemort’s fall, and says he never had much sense."},{"from":5,"text":"He is overjoyed to shake Harry’s hand at the Leaky Cauldron. He once bowed to Harry in a shop."}],"moments":[]},{"id":"dudley-dursley","name":"Dudley Dursley","firstChapter":1,"importance":"supporting","group":"Privet Drive","aliases":[],"tagline":[{"from":1,"text":"The Dursleys’ baby son, whom they consider perfect."},{"from":2,"text":"Harry’s large, spoiled cousin and chief tormentor."}],"description":[{"from":1,"text":"The Dursleys’ son, whom they think the finest boy anywhere."},{"from":2,"text":"Now very large, with a pink face and watery blue eyes, he is utterly spoiled, throws tantrums over birthday presents and leads a gang that bullies Harry."},{"from":4,"text":"Hagrid, angered by Vernon, gives him a curly pig’s tail."}],"moments":[{"chapter":2,"text":"Was nearly caught by the escaped boa at the zoo."},{"chapter":4,"text":"Was given a pig’s tail by Hagrid."}]},{"id":"harry-potter","name":"Harry Potter","firstChapter":1,"importance":"major","group":"Gryffindor","aliases":[{"name":"The Boy Who Lived","from":1,"note":"what the wizarding world calls him"}],"tagline":[{"from":1,"text":"A baby who survived the attack that killed his parents."},{"from":2,"text":"An unloved orphan living in the Dursleys’ cupboard under the stairs."},{"from":4,"text":"An eleven-year-old who has just learned he is a famous wizard."},{"from":7,"text":"A first-year Gryffindor at Hogwarts."},{"from":9,"text":"Gryffindor’s new Seeker, the youngest house player in a century."},{"from":13,"text":"Determined to stop Snape from stealing the Sorcerer’s Stone."},{"from":16,"text":"Going after the Stone himself, through the trapdoor."},{"from":17,"text":"The boy who faced Voldemort again and saved the Stone."}],"description":[{"from":1,"text":"The baby son of Lily and James Potter. When the dark wizard Voldemort killed his parents, he tried to kill Harry too, but failed and vanished, leaving Harry with a lightning-shaped cut on his forehead. Dumbledore leaves him with his aunt and uncle, the Dursleys."},{"from":2,"text":"Ten years later Harry is small and skinny, with untidy black hair, bright green eyes, taped-up glasses and a thin scar. He sleeps in a cupboard, wears Dudley’s cast-offs, and has been told his parents died in a car crash. Odd things happen around him when he is scared or angry, and he seems able to talk to snakes."},{"from":4,"text":"On his eleventh birthday Hagrid tells him the truth: he is a wizard, his parents were murdered, and the failed curse made him famous in the wizarding world. He is offered a place at Hogwarts."},{"from":5,"text":"He turns out to have a vault of gold left by his parents. His wand, holly and phoenix feather, is the brother of the wand that gave him his scar."},{"from":6,"text":"On the Hogwarts Express he quickly befriends Ron Weasley and turns down Draco Malfoy’s offer of friendship. Having never had friends or treats, he shares a whole sweet trolley."},{"from":7,"text":"The Sorting Hat considers Slytherin for him, but he begs not to go there and is placed in Gryffindor. His scar hurts when he first meets Snape’s eyes across the hall."},{"from":9,"text":"He is a natural flier, and McGonagall makes him Gryffindor’s Seeker. He is brave and quick to defend others, but also easily drawn into rule-breaking."},{"from":10,"text":"With Ron he rescues Hermione from a troll, and the three become close friends."},{"from":12,"text":"He receives his father’s Invisibility Cloak and finds the Mirror of Erised, which shows him the family he never knew. Dumbledore gently warns him not to dwell on dreams."},{"from":15,"text":"After losing Gryffindor 150 points he is shunned by the school. In the Forbidden Forest his scar burns near the hooded figure drinking unicorn blood, and he becomes convinced Voldemort is trying to return."},{"from":17,"text":"Harry learns that his mother’s sacrifice left a protection on him that Quirrell, possessed by Voldemort, could not bear to touch. He got the Stone from the mirror because he wanted to find it but not use it. He goes home a hero to his house, but back to the Dursleys for the summer."}],"moments":[{"chapter":1,"text":"Survived Voldemort’s attack as a baby and was left on the Dursleys’ doorstep."},{"chapter":2,"text":"Talked to a boa constrictor at the zoo; the tank’s glass vanished."},{"chapter":4,"text":"Learned from Hagrid that he is a wizard."},{"chapter":5,"text":"Bought his wand at Ollivanders; it is linked to the wand that scarred him."},{"chapter":6,"text":"Befriended Ron and refused Draco Malfoy’s friendship."},{"chapter":7,"text":"Was sorted into Gryffindor after asking not to be in Slytherin."},{"chapter":9,"text":"Caught Neville’s Remembrall in a dive and became Gryffindor’s Seeker."},{"chapter":9,"text":"Found the three-headed dog guarding a trapdoor."},{"chapter":10,"text":"Fought a mountain troll with Ron to save Hermione."},{"chapter":11,"text":"Won his first Quidditch match by catching the Snitch in his mouth."},{"chapter":12,"text":"Received the Invisibility Cloak and saw his family in the Mirror of Erised."},{"chapter":14,"text":"Smuggled Norbert to Charlie’s friends, but was caught out of bed."},{"chapter":15,"text":"Was saved by Firenze from the hooded figure in the forest."},{"chapter":16,"text":"Caught the winged key and went on alone through the black flames."},{"chapter":17,"text":"Got the Stone from the mirror and resisted Quirrell and Voldemort."}]},{"id":"james-potter","name":"James Potter","firstChapter":1,"importance":"supporting","group":"Harry’s family & past","aliases":[],"tagline":[{"from":1,"text":"Harry’s father, killed by Voldemort."}],"description":[{"from":1,"text":"Harry’s father, killed along with his wife Lily by Voldemort."},{"from":4,"text":"A wizard, and Head Boy at Hogwarts in his day."},{"from":9,"text":"McGonagall mentions he was an excellent Quidditch player."},{"from":12,"text":"Harry learns the Invisibility Cloak was his, and sees him in the mirror: tall and thin, with hair as untidy as Harry’s."},{"from":17,"text":"Dumbledore reveals that James once saved Snape’s life, and that he and Snape loathed each other."}],"moments":[{"chapter":12,"text":"Left Harry his Invisibility Cloak."}]},{"id":"lily-potter","name":"Lily Potter","firstChapter":1,"importance":"supporting","group":"Harry’s family & past","aliases":[],"tagline":[{"from":1,"text":"Harry’s mother, killed by Voldemort."},{"from":17,"text":"Harry’s mother, whose sacrifice still protects him."}],"description":[{"from":1,"text":"Harry’s mother and Petunia Dursley’s sister. She and her husband James were killed by Voldemort at their home in Godric’s Hollow."},{"from":4,"text":"She was a witch, and Hagrid says she and James were Head Girl and Head Boy in their day. Petunia resented her."},{"from":12,"text":"In the Mirror of Erised, Harry sees her: a pretty woman with dark red hair and eyes just like his."},{"from":17,"text":"Dumbledore explains that she died to save Harry, and that love so strong left a protection in his very skin."}],"moments":[{"chapter":17,"text":"Was revealed to have protected Harry by dying for him."}]},{"id":"minerva-mcgonagall","name":"Professor McGonagall","firstChapter":1,"importance":"major","group":"Hogwarts staff","aliases":[{"name":"the tabby cat on Privet Drive","from":1,"note":"she can turn into a cat"}],"tagline":[{"from":1,"text":"A stern witch who can turn into a tabby cat."},{"from":7,"text":"Deputy head, Transfiguration teacher and head of Gryffindor."}],"description":[{"from":1,"text":"A severe-looking witch with square glasses and her hair in a tight bun. She spends the day on Privet Drive disguised as a tabby cat, and objects strongly to leaving Harry with the Dursleys."},{"from":7,"text":"She meets the first-years and runs the Sorting. She is head of Gryffindor house: strict, but fair."},{"from":8,"text":"She teaches Transfiguration, a complex and dangerous subject, and turns her desk into a pig to show the class."},{"from":9,"text":"Seeing Harry’s flying, she breaks the rules to make him Gryffindor Seeker, and later sends him a Nimbus Two Thousand. She is a keen Quidditch fan."},{"from":15,"text":"She takes a shocking 150 points from Gryffindor after Harry, Hermione and Neville are caught out at night."},{"from":16,"text":"She refuses to believe the Stone is in danger when Harry warns her."}],"moments":[{"chapter":1,"text":"Watched the Dursleys all day disguised as a cat."},{"chapter":9,"text":"Made Harry the Gryffindor Seeker."},{"chapter":14,"text":"Caught Malfoy out of bed on the night of Norbert’s departure."},{"chapter":15,"text":"Took 150 points from Gryffindor."}]},{"id":"petunia-dursley","name":"Petunia Dursley","firstChapter":1,"importance":"supporting","group":"Privet Drive","aliases":[{"name":"Aunt Petunia","from":2}],"tagline":[{"from":1,"text":"A thin, nosy woman who pretends her sister doesn’t exist."},{"from":4,"text":"Harry’s aunt, the non-magical sister of his mother, Lily."}],"description":[{"from":1,"text":"Thin and blonde with a long neck, ideal for spying on the neighbours. She is Mrs. Potter’s sister but pretends not to have one."},{"from":2,"text":"She dotes on Dudley and treats Harry as a burden."},{"from":4,"text":"She reveals she always knew the truth: her sister Lily was a witch, the favourite of their parents, and Petunia called her a freak. She and Vernon hoped to stamp the magic out of Harry."}],"moments":[{"chapter":4,"text":"Burst out that her sister Lily was a witch."}]},{"id":"rubeus-hagrid","name":"Hagrid","firstChapter":1,"importance":"major","group":"Hogwarts staff","aliases":[{"name":"Rubeus Hagrid","from":4},{"name":"Keeper of Keys and Grounds at Hogwarts","from":4}],"tagline":[{"from":1,"text":"An enormous, wild-haired man who brings baby Harry on a flying motorbike."},{"from":4,"text":"Hogwarts’ gamekeeper, who tells Harry he’s a wizard."},{"from":14,"text":"Hogwarts’ gamekeeper, secretly raising a baby dragon."},{"from":16,"text":"Harry’s loyal friend, who accidentally gave away how to pass Fluffy."}],"description":[{"from":1,"text":"Almost twice the height of a normal man, with a shaggy black beard. He rescued baby Harry from his parents’ ruined house and weeps when Dumbledore leaves him with the Dursleys."},{"from":4,"text":"He is Keeper of Keys and Grounds at Hogwarts and fiercely loyal to Dumbledore. He tells Harry the truth about his parents, and gives Dudley a pig’s tail. He was expelled from Hogwarts in his third year, so he is not supposed to do magic, and keeps his broken wand in a pink umbrella."},{"from":5,"text":"He takes Harry shopping in Diagon Alley, buys him an owl, and collects a mysterious package from vault 713 for Dumbledore."},{"from":8,"text":"He lives in a wooden hut by the Forbidden Forest with his boarhound Fang, makes rock cakes that break your teeth, and becomes a friend to Harry and Ron. He dodges questions about the Gringotts break-in."},{"from":11,"text":"He loves dangerous creatures: the three-headed dog Fluffy is his. He lets slip the name Nicolas Flamel."},{"from":12,"text":"For Christmas he carves Harry a wooden flute."},{"from":14,"text":"He has always wanted a dragon and wins an egg in a card game from a hooded stranger. He hatches Norbert and is heartbroken to give him up."},{"from":16,"text":"He realizes he told the stranger how to get past Fluffy: play it music."},{"from":17,"text":"Full of guilt, he gives Harry a photo album of his parents."}],"moments":[{"chapter":1,"text":"Brought baby Harry to Privet Drive on a flying motorbike."},{"chapter":4,"text":"Broke down the door and told Harry he is a wizard."},{"chapter":5,"text":"Collected a small package from Gringotts vault 713."},{"chapter":11,"text":"Let slip Fluffy’s name and Nicolas Flamel’s."},{"chapter":14,"text":"Hatched a baby dragon, Norbert."},{"chapter":15,"text":"Led the detention in the Forbidden Forest."},{"chapter":16,"text":"Admitted he told a stranger how to get past Fluffy."},{"chapter":17,"text":"Gave Harry a photo album of his parents."}]},{"id":"sirius-black","name":"Sirius Black","firstChapter":1,"importance":"minor","group":"Harry’s family & past","aliases":[],"tagline":[{"from":1,"text":"The “young” wizard who lent Hagrid his flying motorbike."}],"description":[{"from":1,"text":"Mentioned only in passing: Hagrid borrowed the flying motorbike he used to bring baby Harry from young Sirius Black."}],"moments":[]},{"id":"vernon-dursley","name":"Vernon Dursley","firstChapter":1,"importance":"supporting","group":"Privet Drive","aliases":[{"name":"Uncle Vernon","from":2}],"tagline":[{"from":1,"text":"A beefy, mustached businessman who hates anything unusual."},{"from":2,"text":"Harry’s uncle, who treats him like a nuisance."}],"description":[{"from":1,"text":"A big, beefy man with hardly any neck and a large mustache, director of a drill company called Grunnings. He is proud of being perfectly normal and is unsettled by all the strange goings-on."},{"from":2,"text":"As Harry’s uncle, he bullies him, forbids questions and punishes him for every odd event, while spoiling his own son."},{"from":3,"text":"He goes to absurd lengths to stop Harry getting his letters, finally fleeing to a shack on a rock in the sea."},{"from":4,"text":"He refuses to let Harry go to Hogwarts and insults Dumbledore, which Hagrid will not stand for."}],"moments":[{"chapter":3,"text":"Destroyed Harry’s letter and fled the house to escape the rest."},{"chapter":6,"text":"Dropped Harry at King’s Cross and mocked him."}]},{"id":"voldemort","name":"Voldemort","firstChapter":1,"importance":"major","group":"Voldemort","aliases":[{"name":"You-Know-Who","from":1,"note":"most wizards fear to say his name"},{"name":"He-Who-Must-Not-Be-Named","from":4}],"tagline":[{"from":1,"text":"The feared dark wizard who killed Harry’s parents, then vanished."},{"from":15,"text":"The vanished dark wizard, perhaps trying to return."},{"from":17,"text":"The dark wizard living as a face on the back of Quirrell’s head."}],"description":[{"from":1,"text":"A dark wizard so feared that most people won’t say his name. He killed Lily and James Potter, but when he tried to kill baby Harry his power somehow broke, and he disappeared."},{"from":4,"text":"Hagrid explains that he gathered followers and terrorized the wizarding world for years. Hagrid doesn’t think he died: he is out there somewhere, too weak to carry on."},{"from":5,"text":"He was a Slytherin. The wand that gave Harry his scar is the brother of Harry’s own wand."},{"from":15,"text":"Firenze hints that someone desperate is drinking unicorn blood to survive while waiting for the Stone, and Harry realizes he means Voldemort."},{"from":17,"text":"He has been living as a parasite on Quirrell, his face on the back of Quirrell’s head, kept alive by unicorn blood. He wanted the Stone to make himself a new body. Thwarted, he left Quirrell to die and fled, but is still out there."}],"moments":[{"chapter":1,"text":"Killed Lily and James Potter but failed to kill Harry."},{"chapter":17,"text":"Offered to bring back Harry’s parents in exchange for the Stone."},{"chapter":17,"text":"Abandoned Quirrell and fled."}]},{"id":"arabella-figg","name":"Mrs. Figg","firstChapter":2,"importance":"minor","group":"Privet Drive","aliases":[],"tagline":[{"from":2,"text":"The Dursleys’ cat-obsessed neighbour, who minds Harry."}],"description":[{"from":2,"text":"An old lady two streets away whose house smells of cabbage and who makes Harry look at photos of all her cats. The Dursleys leave Harry with her on Dudley’s birthday, but this year she has broken her leg."}],"moments":[]},{"id":"piers-polkiss","name":"Piers Polkiss","firstChapter":2,"importance":"minor","group":"Privet Drive","aliases":[],"tagline":[{"from":2,"text":"Dudley’s scrawny, rat-faced best friend."}],"description":[{"from":2,"text":"Dudley’s best friend, who usually holds people’s arms behind their backs while Dudley hits them. He comes to the zoo, and afterwards says Harry was talking to the snake."}],"moments":[]},{"id":"garrick-ollivander","name":"Mr. Ollivander","firstChapter":5,"importance":"supporting","group":"Wizarding world","aliases":[],"tagline":[{"from":5,"text":"The silvery-eyed wandmaker who sells Harry his wand."}],"description":[{"from":5,"text":"An old man with pale, moonlike eyes who remembers every wand he has sold, including Harry’s parents’ wands. He says the wand chooses the wizard. Harry’s holly and phoenix-feather wand shares its core with the wand that gave him his scar, which Ollivander finds curious: he expects great things."}],"moments":[{"chapter":5,"text":"Sold Harry his holly and phoenix-feather wand."}]},{"id":"griphook","name":"Griphook","firstChapter":5,"importance":"minor","group":"Wizarding world","aliases":[],"tagline":[{"from":5,"text":"A goblin at Gringotts bank."}],"description":[{"from":5,"text":"He takes Harry and Hagrid down to the vaults by rattling cart, to Harry’s vault and then to vault 713."}],"moments":[]},{"id":"madam-malkin","name":"Madam Malkin","firstChapter":5,"importance":"minor","group":"Wizarding world","aliases":[],"tagline":[{"from":5,"text":"A squat, smiling witch who sells robes in Diagon Alley."}],"description":[{"from":5,"text":"Her shop, Robes for All Occasions, is where Harry is fitted for his school robes."}],"moments":[]},{"id":"pale-boy","name":"The pale boy at Madam Malkin’s","firstChapter":5,"importance":"minor","group":"Slytherin","aliases":[],"tagline":[{"from":5,"text":"A snobbish boy Harry meets being fitted for robes."}],"description":[{"from":5,"text":"A boy with a pale, pointed face, being fitted for Hogwarts robes next to Harry. He talks in a bored drawl about bullying his father into buying him a racing broom, is sure he’ll be in Slytherin, calls Hagrid a savage, and thinks children from Muggle families shouldn’t be allowed at Hogwarts. Harry dislikes him at once."}],"moments":[{"chapter":5,"text":"Sneered at Hagrid in Madam Malkin’s."}],"mergedInto":{"id":"draco-malfoy","from":6}},{"id":"quirinus-quirrell","name":"Professor Quirrell","firstChapter":5,"importance":"major","group":"Hogwarts staff","aliases":[],"tagline":[{"from":5,"text":"A pale, nervous young wizard with a stutter."},{"from":8,"text":"The jittery Defence Against the Dark Arts teacher in a purple turban."},{"from":13,"text":"The timid teacher Harry thinks is standing up to Snape."},{"from":17,"text":"Voldemort’s servant, sharing his body under the turban."}],"description":[{"from":5,"text":"Harry meets him in the Leaky Cauldron. He is pale, twitchy and stammers badly. He will teach Defence Against the Dark Arts at Hogwarts. Hagrid says he was brilliant until he took a year off to get first-hand experience and had a bad time with a hag."},{"from":7,"text":"At the feast he wears a large purple turban and sits beside Snape."},{"from":8,"text":"His classroom reeks of garlic, said to keep away a vampire he met in Romania. He claims the turban was a gift from an African prince for getting rid of a troublesome zombie, but goes pink when asked how."},{"from":10,"text":"He bursts into the Halloween feast to announce a troll in the dungeons, and faints."},{"from":11,"text":"Hermione knocks him over in the stands as she runs to stop Snape."},{"from":13,"text":"Harry overhears Snape menacing him in the forest. The friends believe he has protected the Stone with a spell, and that Snape is trying to make him give it up."},{"from":15,"text":"Harry hears him pleading with someone, “not again, please,” and fears Snape has broken him."},{"from":17,"text":"The real villain. He jinxed Harry’s broom, let in the troll, and was trying to steal the Stone for Voldemort, whom he met in Albania; it was he, carrying Voldemort, who drank the unicorn’s blood in the forest. Voldemort’s face is on the back of his head under the turban. He cannot bear Harry’s touch, and Voldemort abandons him to die."}],"moments":[{"chapter":5,"text":"Shook Harry’s hand nervously in the Leaky Cauldron."},{"chapter":10,"text":"Announced the troll at the Halloween feast and fainted."},{"chapter":13,"text":"Was cornered by Snape in the Forbidden Forest."},{"chapter":15,"text":"Was overheard begging “not again.”"},{"chapter":17,"text":"Revealed himself as Voldemort’s servant and tried to take the Stone from Harry."}]},{"id":"tom-the-barman","name":"Tom","firstChapter":5,"importance":"minor","group":"Wizarding world","aliases":[],"tagline":[{"from":5,"text":"The bald, toothless barman of the Leaky Cauldron."}],"description":[{"from":5,"text":"He keeps the Leaky Cauldron, the hidden wizarding pub on Charing Cross Road, and is awed to see Harry Potter."}],"moments":[]},{"id":"bill-weasley","name":"Bill Weasley","firstChapter":6,"importance":"minor","group":"The Weasley family","aliases":[],"tagline":[{"from":6,"text":"Ron’s eldest brother, a former Head Boy."}],"description":[{"from":6,"text":"The eldest Weasley brother. He was Head Boy and now works for Gringotts in Africa."}],"moments":[]},{"id":"charlie-weasley","name":"Charlie Weasley","firstChapter":6,"importance":"minor","group":"The Weasley family","aliases":[],"tagline":[{"from":6,"text":"Ron’s brother, who studies dragons in Romania."},{"from":14,"text":"Ron’s dragon-keeper brother, who takes in Norbert."}],"description":[{"from":6,"text":"The second Weasley brother. He was Quidditch captain at Hogwarts and now studies dragons in Romania."},{"from":14,"text":"He agrees to take Norbert, and sends friends to collect the dragon from the top of the tallest tower."}],"moments":[{"chapter":14,"text":"Arranged for his friends to collect Norbert."}]},{"id":"draco-malfoy","name":"Draco Malfoy","firstChapter":6,"importance":"major","group":"Slytherin","aliases":[{"name":"Malfoy","from":6}],"tagline":[{"from":6,"text":"A snobbish boy whose offer of friendship Harry turns down."},{"from":7,"text":"A Slytherin first-year and Harry’s rival."}],"description":[{"from":6,"text":"The pale, drawling boy from Madam Malkin’s, who turns up on the train with his bodyguards Crabbe and Goyle. He sneers at the Weasleys and offers to help Harry pick the right friends. When Harry refuses, they become enemies."},{"from":7,"text":"The Sorting Hat puts him in Slytherin the moment it touches his head."},{"from":9,"text":"He snatches Neville’s Remembrall, then tricks Harry into a midnight duel he never intends to attend, hoping Harry will be caught."},{"from":13,"text":"He bullies Neville with a Leg-Locker Curse."},{"from":14,"text":"He sees Norbert hatch and tries to get Harry caught, but is caught out of bed himself."},{"from":15,"text":"In the forest he scares Neville as a joke, and flees screaming from the hooded figure."}],"moments":[{"chapter":6,"text":"Was snubbed by Harry on the train."},{"chapter":9,"text":"Stole Neville’s Remembrall and set up a fake duel."},{"chapter":14,"text":"Got a detention for being out of bed while spying on Harry."},{"chapter":15,"text":"Ran from the hooded figure in the Forbidden Forest."}]},{"id":"fred-weasley","name":"Fred Weasley","firstChapter":6,"importance":"supporting","group":"Gryffindor","aliases":[],"tagline":[{"from":6,"text":"One of Ron’s mischievous twin brothers."},{"from":10,"text":"A prankster twin and Gryffindor Beater."}],"description":[{"from":6,"text":"One of the identical Weasley twins, always joking. He and George help Harry with his trunk and are thrilled to discover who he is."},{"from":10,"text":"He and George are Beaters on the Gryffindor Quidditch team."},{"from":12,"text":"He and George force Percy into his Christmas sweater."}],"moments":[]},{"id":"george-weasley","name":"George Weasley","firstChapter":6,"importance":"supporting","group":"Gryffindor","aliases":[],"tagline":[{"from":6,"text":"One of Ron’s mischievous twin brothers."},{"from":10,"text":"A prankster twin and Gryffindor Beater."}],"description":[{"from":6,"text":"Fred’s identical twin, just as full of jokes. Even their mother can’t always tell them apart."},{"from":10,"text":"He and Fred are Beaters on the Gryffindor Quidditch team."}],"moments":[]},{"id":"ginny-weasley","name":"Ginny Weasley","firstChapter":6,"importance":"minor","group":"The Weasley family","aliases":[],"tagline":[{"from":6,"text":"Ron’s little sister, too young for Hogwarts."}],"description":[{"from":6,"text":"The youngest Weasley and the only girl. She wishes she could go to Hogwarts too, and is excited to see Harry Potter."}],"moments":[]},{"id":"gregory-goyle","name":"Goyle","firstChapter":6,"importance":"minor","group":"Slytherin","aliases":[],"tagline":[{"from":6,"text":"Malfoy’s other bodyguard, bitten by Scabbers."}],"description":[{"from":6,"text":"Malfoy’s second hulking companion. He gets bitten by Scabbers while trying to grab Ron’s sweets."}],"moments":[]},{"id":"hedwig","name":"Hedwig","firstChapter":6,"importance":"minor","group":"Creatures","aliases":[],"tagline":[{"from":6,"text":"Harry’s snowy owl, a birthday present from Hagrid."}],"description":[{"from":6,"text":"Hagrid bought her for Harry in Diagon Alley. Harry named her after a name he found in A History of Magic."},{"from":8,"text":"She brings Harry his first letter at Hogwarts, an invitation to tea from Hagrid."}],"moments":[]},{"id":"hermione-granger","name":"Hermione Granger","firstChapter":6,"importance":"major","group":"Gryffindor","aliases":[],"tagline":[{"from":6,"text":"A bossy, bushy-haired first-year who has memorized all her books."},{"from":10,"text":"Harry and Ron’s clever, rule-abiding new friend."},{"from":16,"text":"Harry and Ron’s brilliant friend, whose logic gets them through."}],"description":[{"from":6,"text":"A first-year from a non-magical family, she has learned all her textbooks by heart and speaks very fast in a bossy voice. She helps Neville look for his toad and already knows all about Harry from books."},{"from":7,"text":"She is sorted into Gryffindor."},{"from":9,"text":"She cares a lot about rules and house points, and tries to stop Harry and Ron going to the midnight duel. But she also notices the trapdoor under the three-headed dog’s feet."},{"from":10,"text":"Hurt by Ron’s mockery, she hides in the bathroom and is cornered by the troll. Afterwards she lies to McGonagall to protect the boys, and becomes their friend."},{"from":11,"text":"Convinced Snape is jinxing Harry’s broom, she sets his robes on fire to break his concentration."},{"from":13,"text":"She finds the book that explains who Nicolas Flamel is and what the Sorcerer’s Stone does."},{"from":16,"text":"She defeats the Devil’s Snare and solves the potion riddle, then goes back to help Ron and send for Dumbledore."},{"from":17,"text":"Dumbledore awards her fifty points for cool logic in the face of fire."}],"moments":[{"chapter":6,"text":"Met Harry and Ron while searching for Neville’s toad."},{"chapter":9,"text":"Opened the locked door to the forbidden corridor with a spell."},{"chapter":10,"text":"Took the blame for the troll incident and became friends with Harry and Ron."},{"chapter":11,"text":"Set Snape’s robes alight during the Quidditch match."},{"chapter":13,"text":"Discovered that Flamel made the Sorcerer’s Stone."},{"chapter":14,"text":"Helped carry Norbert to the tallest tower."},{"chapter":16,"text":"Put Neville in a full Body-Bind and solved the potion riddle."},{"chapter":17,"text":"Earned fifty points for Gryffindor."}]},{"id":"lee-jordan","name":"Lee Jordan","firstChapter":6,"importance":"minor","group":"Gryffindor","aliases":[],"tagline":[{"from":6,"text":"The twins’ friend, who owns a tarantula."},{"from":11,"text":"The twins’ friend and the biased Quidditch commentator."}],"description":[{"from":6,"text":"A boy with dreadlocks and a box containing a giant tarantula, friends with Fred and George."},{"from":11,"text":"He commentates the Quidditch matches, cheering for Gryffindor so openly that McGonagall keeps telling him off."}],"moments":[]},{"id":"molly-weasley","name":"Mrs. Weasley","firstChapter":6,"importance":"supporting","group":"The Weasley family","aliases":[],"tagline":[{"from":6,"text":"Ron’s kind, plump, red-haired mother."}],"description":[{"from":6,"text":"The mother of the Weasley children. She kindly shows a lost Harry how to get onto platform nine and three-quarters."},{"from":12,"text":"She knits Harry a lumpy emerald sweater and sends him homemade fudge for Christmas."},{"from":17,"text":"She thanks Harry warmly at King’s Cross at the end of term."}],"moments":[{"chapter":6,"text":"Helped Harry through the barrier at King’s Cross."}]},{"id":"neville-longbottom","name":"Neville Longbottom","firstChapter":6,"importance":"supporting","group":"Gryffindor","aliases":[{"name":"Neville","from":6}],"tagline":[{"from":6,"text":"A forgetful, round-faced boy who keeps losing his toad."},{"from":7,"text":"A clumsy, nervous Gryffindor first-year."},{"from":17,"text":"The shy Gryffindor who stood up to his friends."}],"description":[{"from":6,"text":"A tearful, round-faced first-year who loses his toad, Trevor, on the train."},{"from":7,"text":"Sorted into Gryffindor. He was raised by his gran, whose family worried he had no magic until he bounced after an uncle dropped him out of a window."},{"from":8,"text":"He is hopeless at Potions and terrified of Snape."},{"from":9,"text":"He breaks his wrist at the first flying lesson, and later gets locked out of the tower because he forgets the password."},{"from":13,"text":"Hexed by Malfoy, he is told by Harry that he is worth twelve of him."},{"from":15,"text":"Trying to warn Harry, he loses fifty points and serves detention in the forest."},{"from":16,"text":"He bravely tries to stop the friends leaving, and is frozen by Hermione."},{"from":17,"text":"Dumbledore awards him ten points, the winning points, for standing up to his friends."}],"moments":[{"chapter":9,"text":"Broke his wrist in the first flying lesson."},{"chapter":16,"text":"Tried to stop Harry, Ron and Hermione leaving the tower."},{"chapter":17,"text":"Earned the ten points that won Gryffindor the House Cup."}]},{"id":"nicolas-flamel","name":"Nicolas Flamel","firstChapter":6,"importance":"supporting","group":"Wizarding world","aliases":[],"tagline":[{"from":6,"text":"Dumbledore’s partner in alchemy, according to a Chocolate Frog card."},{"from":11,"text":"A mysterious name linked to whatever the three-headed dog guards."},{"from":13,"text":"The 665-year-old maker of the Sorcerer’s Stone."}],"description":[{"from":6,"text":"Named on Dumbledore’s Chocolate Frog card as his partner in alchemy."},{"from":11,"text":"Hagrid lets slip that what Fluffy guards is between Dumbledore and Nicolas Flamel."},{"from":13,"text":"The friends learn he is a famous alchemist, the only known maker of the Sorcerer’s Stone, which turns metal into gold and makes the Elixir of Life. He and his wife live quietly in Devon and he is 665 years old."},{"from":17,"text":"He agrees to the Stone’s destruction, knowing he and his wife will die once their supply of Elixir runs out."}],"moments":[{"chapter":17,"text":"Agreed that the Stone should be destroyed."}]},{"id":"percy-weasley","name":"Percy Weasley","firstChapter":6,"importance":"minor","group":"Gryffindor","aliases":[],"tagline":[{"from":6,"text":"Ron’s pompous older brother, a Gryffindor prefect."}],"description":[{"from":6,"text":"The third Weasley brother, very proud of his prefect’s badge."},{"from":7,"text":"He shows the first-years to Gryffindor Tower and tells Harry who Snape is."}],"moments":[]},{"id":"ron-weasley","name":"Ron Weasley","firstChapter":6,"importance":"major","group":"Gryffindor","aliases":[{"name":"Ronald Weasley","from":6}],"tagline":[{"from":6,"text":"The youngest Weasley boy, who becomes Harry’s first friend on the train."},{"from":7,"text":"Harry’s best friend and fellow Gryffindor first-year."},{"from":16,"text":"Harry’s best friend and a brilliant chess player."}],"description":[{"from":6,"text":"Tall, freckled and red-haired, Ron is the sixth of seven Weasley children and feels he has a lot to live up to. His family doesn’t have much money, so he has hand-me-down robes, a hand-me-down rat named Scabbers, and sandwiches his mother forgot he hates. He is warm, funny and loyal, and dislikes the Malfoys."},{"from":7,"text":"He is sorted into Gryffindor like all his family."},{"from":10,"text":"He mocks Hermione as an insufferable know-it-all, but helps rescue her from the troll, making the levitation spell work at the crucial moment. The three become friends."},{"from":12,"text":"In the Mirror of Erised he sees himself as Head Boy and Quidditch captain: standing out from his brothers at last."},{"from":16,"text":"A strong chess player, he leads the way across the giant chessboard and deliberately sacrifices himself so Harry can go on."},{"from":17,"text":"Dumbledore awards him fifty points for the best-played game of chess Hogwarts has seen in years."}],"moments":[{"chapter":6,"text":"Shared Harry’s compartment on the Hogwarts Express."},{"chapter":9,"text":"Acted as Harry’s second in the duel Malfoy never turned up to."},{"chapter":10,"text":"Knocked out the troll with its own club using the levitation spell."},{"chapter":12,"text":"Saw himself as Head Boy in the Mirror of Erised."},{"chapter":14,"text":"Was bitten by Norbert and ended up in the hospital wing."},{"chapter":16,"text":"Sacrificed himself in the giant chess game."},{"chapter":17,"text":"Earned fifty points for Gryffindor for his chess."}]},{"id":"scabbers","name":"Scabbers","firstChapter":6,"importance":"minor","group":"Creatures","aliases":[],"tagline":[{"from":6,"text":"Ron’s fat, sleepy, hand-me-down rat."}],"description":[{"from":6,"text":"Ron’s pet rat, who used to belong to Percy and spends most of his time asleep. He bites Goyle when Malfoy’s gang tries to steal sweets."}],"moments":[{"chapter":6,"text":"Bit Goyle on the Hogwarts Express."}]},{"id":"vincent-crabbe","name":"Crabbe","firstChapter":6,"importance":"minor","group":"Slytherin","aliases":[],"tagline":[{"from":6,"text":"One of Malfoy’s thickset bodyguards."}],"description":[{"from":6,"text":"A big, mean-looking boy who follows Draco Malfoy everywhere."},{"from":9,"text":"He is meant to be Malfoy’s second in the midnight duel."}],"moments":[]},{"id":"argus-filch","name":"Argus Filch","firstChapter":7,"importance":"supporting","group":"Hogwarts staff","aliases":[{"name":"Filch","from":7}],"tagline":[{"from":7,"text":"The bad-tempered caretaker who longs to catch rule-breakers."}],"description":[{"from":7,"text":"Hogwarts’ caretaker. Dumbledore mentions his long list of forbidden items."},{"from":8,"text":"He knows the castle’s secret passages and, with his cat Mrs. Norris, seems to appear wherever students break rules."},{"from":11,"text":"Harry finds him bandaging Snape’s injured leg."},{"from":14,"text":"He catches Harry and Hermione coming down from the tallest tower after midnight."},{"from":15,"text":"He relishes delivering the detention, and misses the old punishments."}],"moments":[{"chapter":14,"text":"Caught Harry and Hermione out of bed."}]},{"id":"bloody-baron","name":"The Bloody Baron","firstChapter":7,"importance":"minor","group":"Ghosts & castle","aliases":[],"tagline":[{"from":7,"text":"Slytherin’s gaunt, blood-stained ghost."}],"description":[{"from":7,"text":"The ghost of Slytherin, with blank staring eyes and silver bloodstains. He is the only one who can control Peeves."}],"moments":[]},{"id":"dean-thomas","name":"Dean Thomas","firstChapter":7,"importance":"minor","group":"Gryffindor","aliases":[],"tagline":[{"from":7,"text":"A Gryffindor first-year who shares Harry’s dormitory."}],"description":[{"from":7,"text":"One of the boys sorted into Gryffindor with Harry, Ron, Neville and Seamus."}],"moments":[]},{"id":"fat-friar","name":"The Fat Friar","firstChapter":7,"importance":"minor","group":"Ghosts & castle","aliases":[],"tagline":[{"from":7,"text":"Hufflepuff’s forgiving ghost."}],"description":[{"from":7,"text":"A cheerful ghost who greets the first-years and suggests giving Peeves a second chance."}],"moments":[]},{"id":"fat-lady","name":"The Fat Lady","firstChapter":7,"importance":"minor","group":"Ghosts & castle","aliases":[],"tagline":[{"from":7,"text":"The portrait that guards Gryffindor Tower."}],"description":[{"from":7,"text":"A very fat woman in a pink silk dress, painted in a portrait that swings open to let Gryffindors into their common room when they give the password."}],"moments":[]},{"id":"nearly-headless-nick","name":"Nearly Headless Nick","firstChapter":7,"importance":"minor","group":"Ghosts & castle","aliases":[{"name":"Sir Nicholas de Mimsy-Porpington","from":7}],"tagline":[{"from":7,"text":"Gryffindor’s ruffled-collar ghost."}],"description":[{"from":7,"text":"The ghost of Gryffindor Tower. His head is attached to his neck by a mere sliver of skin, which he demonstrates at the feast."}],"moments":[]},{"id":"peeves","name":"Peeves","firstChapter":7,"importance":"minor","group":"Ghosts & castle","aliases":[],"tagline":[{"from":7,"text":"A troublemaking poltergeist."}],"description":[{"from":7,"text":"A poltergeist who plays tricks on students, throwing walking sticks at the first-years on their way to bed."},{"from":9,"text":"He nearly gives Harry and his friends away to Filch on the night of the duel."},{"from":16,"text":"Under the cloak, Harry fools him by pretending to be the Bloody Baron."}],"moments":[]},{"id":"seamus-finnigan","name":"Seamus Finnigan","firstChapter":7,"importance":"minor","group":"Gryffindor","aliases":[],"tagline":[{"from":7,"text":"A sandy-haired Gryffindor first-year."}],"description":[{"from":7,"text":"A Gryffindor in Harry’s year. His mother is a witch and his father a Muggle, who didn’t find out until after the wedding."}],"moments":[]},{"id":"severus-snape","name":"Professor Snape","firstChapter":7,"importance":"major","group":"Hogwarts staff","aliases":[{"name":"Severus Snape","from":7}],"tagline":[{"from":7,"text":"A sallow, hook-nosed teacher whose look makes Harry’s scar hurt."},{"from":8,"text":"The Potions master, who seems to hate Harry."},{"from":11,"text":"Potions master whom Harry suspects of jinxing his broom."},{"from":13,"text":"Potions master whom Harry believes is trying to steal the Stone."},{"from":17,"text":"Harry’s bitter enemy, who secretly protected him all year."}],"description":[{"from":7,"text":"A teacher with greasy black hair, a hooked nose and sallow skin. When he glances at Harry over Quirrell’s turban, Harry’s scar burns. Percy says he teaches Potions and wants the Defence Against the Dark Arts job."},{"from":8,"text":"He keeps his class silent without effort and singles Harry out from the first lesson, sneering at his fame and taking points unfairly. He favours his own house, Slytherin."},{"from":11,"text":"Harry sees his leg badly mauled and hears him mention “all three heads,” and suspects he tried to get past the three-headed dog. At the match, Hermione sees him staring at Harry and muttering as the broom goes wild."},{"from":13,"text":"He referees the next match. Harry overhears him threatening Quirrell in the forest about getting past Hagrid’s beast, and the friends believe he is after the Stone."},{"from":14,"text":"Hagrid says he helped protect the Stone."},{"from":17,"text":"The truth: his muttering at the match was a counter-curse to save Harry, he refereed to stop Quirrell trying again, and he was suspicious of Quirrell all along. Dumbledore explains that Harry’s father once saved Snape’s life; Snape hated James, but protected Harry to repay the debt."}],"moments":[{"chapter":8,"text":"Humiliated Harry in his first Potions lesson."},{"chapter":11,"text":"Was seen with a badly injured leg."},{"chapter":11,"text":"Had his robes set on fire by Hermione during the match."},{"chapter":13,"text":"Refereed the Gryffindor–Hufflepuff match."},{"chapter":13,"text":"Was overheard threatening Quirrell in the forest."},{"chapter":17,"text":"Was revealed to have saved Harry with a counter-curse."}]},{"id":"sorting-hat","name":"The Sorting Hat","firstChapter":7,"importance":"minor","group":"Ghosts & castle","aliases":[],"tagline":[{"from":7,"text":"A patched, singing old hat that chooses each student’s house."}],"description":[{"from":7,"text":"It sings about the four houses, then is placed on each new student’s head. It tells Harry he could be great in Slytherin, but listens when he pleads not to go there and puts him in Gryffindor."}],"moments":[{"chapter":7,"text":"Sorted Harry into Gryffindor."}]},{"id":"fang","name":"Fang","firstChapter":8,"importance":"minor","group":"Creatures","aliases":[],"tagline":[{"from":8,"text":"Hagrid’s huge, cowardly boarhound."}],"description":[{"from":8,"text":"An enormous black boarhound who looks fierce but is very friendly and drools on everyone."},{"from":15,"text":"Hagrid admits he’s a coward. He bolts with Malfoy when the hooded figure appears."}],"moments":[]},{"id":"filius-flitwick","name":"Professor Flitwick","firstChapter":8,"importance":"minor","group":"Hogwarts staff","aliases":[],"tagline":[{"from":8,"text":"The tiny, excitable Charms teacher."}],"description":[{"from":8,"text":"So small he stands on a pile of books to teach. When he reaches Harry’s name on the register, he squeaks with excitement and topples out of sight."},{"from":10,"text":"He teaches the levitation charm and praises Hermione’s success."},{"from":14,"text":"Hagrid says he helped protect the Stone."}],"moments":[]},{"id":"mrs-norris","name":"Mrs. Norris","firstChapter":8,"importance":"minor","group":"Ghosts & castle","aliases":[],"tagline":[{"from":8,"text":"Filch’s scrawny, lamp-eyed cat."}],"description":[{"from":8,"text":"Filch’s cat, who patrols the corridors and fetches Filch the moment she spots a student breaking a rule."}],"moments":[]},{"id":"pomona-sprout","name":"Professor Sprout","firstChapter":8,"importance":"minor","group":"Hogwarts staff","aliases":[],"tagline":[{"from":8,"text":"The dumpy witch who teaches Herbology."}],"description":[{"from":8,"text":"She teaches Herbology in the greenhouses behind the castle, about magical plants and fungi."},{"from":14,"text":"Hagrid says she helped protect the Stone."}],"moments":[]},{"id":"professor-binns","name":"Professor Binns","firstChapter":8,"importance":"minor","group":"Hogwarts staff","aliases":[],"tagline":[{"from":8,"text":"The ghost who teaches the very dull History of Magic."}],"description":[{"from":8,"text":"He fell asleep in the staff room one day and got up to teach the next morning, leaving his body behind. His droning lectures are the most boring class."}],"moments":[]},{"id":"oliver-wood","name":"Oliver Wood","firstChapter":9,"importance":"supporting","group":"Gryffindor","aliases":[],"tagline":[{"from":9,"text":"Gryffindor’s burly, Quidditch-obsessed captain."}],"description":[{"from":9,"text":"A fifth-year and the Gryffindor team’s Keeper and captain. He is thrilled when McGonagall brings him a Seeker."},{"from":10,"text":"He teaches Harry the rules of Quidditch and drills the team relentlessly."}],"moments":[{"chapter":10,"text":"Taught Harry how Quidditch is played."}]},{"id":"pansy-parkinson","name":"Pansy Parkinson","firstChapter":9,"importance":"minor","group":"Slytherin","aliases":[],"tagline":[{"from":9,"text":"A hard-faced Slytherin girl who mocks Neville."}],"description":[{"from":9,"text":"A Slytherin first-year who jeers at Parvati for defending Neville after his fall."}],"moments":[]},{"id":"rolanda-hooch","name":"Madam Hooch","firstChapter":9,"importance":"minor","group":"Hogwarts staff","aliases":[],"tagline":[{"from":9,"text":"The hawk-eyed flying instructor."}],"description":[{"from":9,"text":"She has short gray hair and yellow eyes like a hawk. She teaches first-year flying and takes Neville to the hospital wing when he falls."}],"moments":[]},{"id":"three-headed-dog","name":"The three-headed dog","firstChapter":9,"importance":"supporting","group":"Creatures","aliases":[{"name":"Fluffy","from":11,"note":"Hagrid’s name for him"}],"tagline":[{"from":9,"text":"A monstrous dog guarding a trapdoor in the forbidden corridor."},{"from":11,"text":"Hagrid’s pet, Fluffy, guarding something for Dumbledore."}],"description":[{"from":9,"text":"A gigantic dog with three heads, filling the room behind a locked door on the forbidden third floor. Hermione notices it is standing on a trapdoor."},{"from":11,"text":"Hagrid admits the dog is his. He bought him from a Greek man he met in a pub and lent him to Dumbledore to guard something."},{"from":16,"text":"Hagrid reveals his weakness: play him music and he falls asleep."}],"moments":[{"chapter":9,"text":"Was discovered guarding a trapdoor."}]},{"id":"mountain-troll","name":"The mountain troll","firstChapter":10,"importance":"minor","group":"Creatures","aliases":[],"tagline":[{"from":10,"text":"A twelve-foot troll loose in the castle on Halloween."}],"description":[{"from":10,"text":"A huge, foul-smelling troll with a tiny head and a wooden club, which corners Hermione in a girls’ bathroom before Harry and Ron knock it out."},{"from":17,"text":"Quirrell admits he let it in."}],"moments":[]},{"id":"marcus-flint","name":"Marcus Flint","firstChapter":11,"importance":"minor","group":"Slytherin","aliases":[],"tagline":[{"from":11,"text":"The Slytherin Quidditch captain, who plays dirty."}],"description":[{"from":11,"text":"A big sixth-year who captains the Slytherin team and blocks Harry on purpose during the match."}],"moments":[]},{"id":"madam-pomfrey","name":"Madam Pomfrey","firstChapter":14,"importance":"minor","group":"Hogwarts staff","aliases":[],"tagline":[{"from":14,"text":"The strict nurse who runs the hospital wing."}],"description":[{"from":14,"text":"She treats Ron’s swollen hand after Norbert bites him, though he claims a dog did it."},{"from":17,"text":"She guards Harry fiercely while he recovers."}],"moments":[]},{"id":"norbert","name":"Norbert","firstChapter":14,"importance":"minor","group":"Creatures","aliases":[],"tagline":[{"from":14,"text":"Hagrid’s baby Norwegian Ridgeback dragon."}],"description":[{"from":14,"text":"A dragon hatched from the egg Hagrid won in a card game. He grows fast, sets things on fire and bites Ron. Since dragon breeding is illegal, he is smuggled away at midnight to Charlie Weasley’s friends."}],"moments":[{"chapter":14,"text":"Was carried off to Romania by Charlie’s friends."}]},{"id":"bane","name":"Bane","firstChapter":15,"importance":"minor","group":"The Forbidden Forest","aliases":[],"tagline":[{"from":15,"text":"A wild-looking, black-haired centaur."}],"description":[{"from":15,"text":"A fierce centaur who believes centaurs must not interfere with what the stars foretell. He is furious that Firenze carries Harry to safety."}],"moments":[]},{"id":"firenze","name":"Firenze","firstChapter":15,"importance":"supporting","group":"The Forbidden Forest","aliases":[],"tagline":[{"from":15,"text":"A young palomino centaur who saves Harry in the forest."}],"description":[{"from":15,"text":"A blond centaur with astonishing blue eyes. He drives off the hooded figure, lets Harry ride on his back, and defies Bane to help him. He explains what drinking unicorn blood means, and hints at who would do it."}],"moments":[{"chapter":15,"text":"Rescued Harry from the hooded figure."}]},{"id":"hooded-figure","name":"The hooded figure in the forest","firstChapter":15,"importance":"supporting","group":"Voldemort","aliases":[],"tagline":[{"from":15,"text":"A cloaked shape that drinks the blood of a dead unicorn."}],"description":[{"from":15,"text":"In the Forbidden Forest, Harry sees a hooded figure crawl out of the shadows and drink a dead unicorn’s silvery blood. Harry’s scar burns as it glides toward him, until Firenze drives it away. Firenze hints that only someone desperate, waiting for the Stone, would do such a thing, and Harry concludes it is Voldemort."}],"moments":[{"chapter":15,"text":"Drank a dead unicorn’s blood and advanced on Harry."}],"mergedInto":{"id":"quirinus-quirrell","from":17}},{"id":"ronan","name":"Ronan","firstChapter":15,"importance":"minor","group":"The Forbidden Forest","aliases":[],"tagline":[{"from":15,"text":"A red-haired centaur who speaks in riddles."}],"description":[{"from":15,"text":"A centaur Hagrid meets in the forest. Asked about the unicorn killer, he says only that Mars is bright tonight, and that the forest hides many secrets."}],"moments":[]}]`)};export{t as default};